/*JSON{
  "type" : "method",
  "class" : "Graphics",
  "name" : "setFontZ100",
  "generate" : "jswrap_graphics_setFontZ100",
  "params" : [
    ["scale","int","[optional] If >1 the font will be scaled up by that amount"]
  ],
  "return" : ["JsVar","The instance of Graphics this was called on, to allow call chaining"],
  "return_object" : "Graphics"
}
Set the current font to Z100 (1 bpp, 9px tall)
*/
JsVar *jswrap_graphics_setFontZ100(JsVar *parent, int scale) {
  if (scale<1) scale=1;
  JsVar *bitmap = jsvNewNativeString((char *)fontBitmap, sizeof(fontBitmap));
  JsVar *widths = jsvNewNativeString((char *)fontWidths, sizeof(fontWidths));
  JsVar *r = jswrap_graphics_setFontCustom(parent, bitmap, 0, widths, 9 + (scale<<8) + (1<<16)); // 1 bit, total height 9px
  jsvUnLock2(bitmap, widths);
  return r;
}
